const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='';
const button=(text,href,cls='')=>`<a class="btn ${cls}" href="${href}">${text}${arrow}</a>`;
let D,selectedType='All',query='',trip=null;let fleetFilters={passengers:0,transmission:''};
