function header(){return `<a href="#main" class="skip-link">Skip to content</a><div class="sticky-nav"><header class="site-header wrap"><div class="header-left"><a href="index.html" aria-label="Dollar Thrifty St. Maarten home"><img class="logo" src="assets/logo.png" alt="Dollar / Thrifty Car Rental" width="2301" height="379"></a></div><nav class="nav" id="main-nav" aria-label="Main navigation">${[['home','Home'],['fleet','Our fleet'],['locations','Locations'],['about','About us'],['contact','Contact']].map(([p,t])=>`<a href="${p==='home'?'index':p}.html" ${page===p?'aria-current="page"':''}>${t}</a>`).join('')}</nav><div class="header-actions">${button('Book a car','index.html#booking','blue')}<button class="menu-toggle" aria-label="Open navigation" aria-controls="main-nav" aria-expanded="false">☰</button></div></header></div>`;}
function footer(){return `<footer class="footer"><div class="wrap"><div class="footer-top"><div><a href="index.html"><img class="footer-logo" src="assets/logo.png" alt="Dollar / Thrifty"></a><p>Best Cars · Best Rates · Best Service</p><div class="socials"><a href="https://www.facebook.com/DollarThriftyCarRentalSXM" target="_blank" rel="noopener" aria-label="Facebook (opens in a new tab)"><svg viewBox="0 0 24 24" aria-hidden="true" fill="currentColor"><path d="M14 21v-8h2.7l.4-3H14V8c0-.9.3-1.5 1.6-1.5h1.7V3.8a23 23 0 0 0-2.5-.1c-2.5 0-4.2 1.5-4.2 4.3v2H8v3h2.6v8H14Z"/></svg></a><a href="https://instagram.com/dollarthriftysxm" target="_blank" rel="noopener" aria-label="Instagram (opens in a new tab)"><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.7"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor" stroke="none"/></svg></a></div></div><div><h4>Explore</h4><nav><a href="fleet.html">Our fleet</a><a href="locations.html">Rental locations</a><a href="about.html">Our story & team</a><a href="services.html">Services & extras</a><a href="reservations.html">My reservation</a></nav></div><div><h4>Useful Information</h4><nav><a href="faq.html">Frequently asked questions</a><a href="policies.html">Rental policies & documents</a><a href="${BASE}assets/documents/Dollar_Thrifty_Terms_and_Conditions.pdf" target="_blank" rel="noopener">Terms and Conditions</a><a href="${BASE}assets/documents/Dollar_Thrifty_Rental_Policies.pdf" target="_blank" rel="noopener">Rental Policies</a><a href="cookie-policy.html">Cookie Policy</a><a href="content-checklist.html">Redesign content checklist</a></nav></div><div><h4>Get In Touch</h4><p>102 Airport Road — St. Maarten<br><a href="tel:+17215452393">+1 (721) 545-2393</a><br><a href="mailto:customerservice@dollarthriftysxm.com">customerservice@dollarthriftysxm.com</a></p><p>From the U.S.: <a href="tel:+18669780932">+1 (866) 978-0932</a><br>From Canada: <a href="tel:+14166282863">+1 (416) 628-2863</a></p></div></div><div class="footer-bottom"><span>© 2026 Dollar/Thrifty Car Rental SXM. Trademarks and brands are the property of their respective owners.</span><span>Original website powered by Logic. IT Solutions.</span></div></div></footer>`;}
const options=(list,valueKey='value',labelKey='label')=>list.map(l=>`<option value="${esc(l[valueKey])}">${esc(l[labelKey])}</option>`).join('');
function timeLabel(value){const [h,m]=value.split(':').map(Number);return `${h%12||12}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`;}
function nextBookingTime(value,part,direction){const [h,m]=value.split(':').map(Number);let minutes=h*60+m;if(part==='period')minutes=(h>=12?8:12)*60+m;else minutes+=direction*(part==='hour'?60:30);minutes=Math.max(480,Math.min(1020,minutes));return `${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`;}
function timePicker(name,label){const chevron='<svg viewBox="0 0 20 20" aria-hidden="true"><path d="m4 12 6-6 6 6"/></svg>';return `<div class="time-picker" data-time-picker><input type="hidden" name="${name}" value="10:00"><button class="time-trigger" type="button" aria-label="${label}, 10:00 AM" aria-haspopup="dialog" aria-expanded="false" aria-controls="${name}-clock"><span data-time-label>10:00 AM</span><svg class="clock-icon" viewBox="0 0 20 20" aria-hidden="true"><circle cx="10" cy="10" r="7.5"/><path d="M10 5.5V10l3 2"/></svg></button><div class="time-popover" id="${name}-clock" role="dialog" aria-label="${label}" hidden><div class="clock-spinner">${['hour','minute','period'].map((part,i)=>`${i===1?'<span class="clock-colon" aria-hidden="true">:</span>':''}<div class="clock-column"><button type="button" data-clock-part="${part}" data-clock-step="1" aria-label="Increase ${label.toLowerCase()} ${part}">${chevron}</button><span class="clock-value" data-clock-value="${part}" role="spinbutton" tabindex="0" aria-label="${label} ${part}" aria-valuemin="${part==='hour'?1:0}" aria-valuemax="${part==='hour'?12:part==='minute'?30:1}" aria-valuenow="${part==='hour'?10:0}">${part==='hour'?'10':part==='minute'?'00':'AM'}</span><button type="button" class="clock-down" data-clock-part="${part}" data-clock-step="-1" aria-label="Decrease ${label.toLowerCase()} ${part}">${chevron}</button></div>`).join('')}</div><span class="sr-only" data-clock-announcement aria-live="polite">10:00 AM</span></div></div>`;}
function wireTimePickers(){const pickers=[...document.querySelectorAll('[data-time-picker]')];function closeAll(except){pickers.forEach(p=>{if(p!==except){p.querySelector('.time-popover').hidden=true;p.querySelector('.time-trigger').setAttribute('aria-expanded','false');}});}function update(p,part,step){const input=p.querySelector('input[type="hidden"]');input.value=nextBookingTime(input.value,part,step);const [hour,minute]=input.value.split(':').map(Number),label=timeLabel(input.value),trigger=p.querySelector('.time-trigger');p.querySelector('[data-time-label]').textContent=label;trigger.setAttribute('aria-label',p.querySelector('.time-popover').getAttribute('aria-label')+', '+label);for(const [part,value,number] of [['hour',String(hour%12||12),hour%12||12],['minute',String(minute).padStart(2,'0'),minute],['period',hour>=12?'PM':'AM',hour>=12?1:0]]){const el=p.querySelector(`[data-clock-value="${part}"]`);el.textContent=value;el.setAttribute('aria-valuenow',String(number));el.setAttribute('aria-valuetext',value);}p.querySelector('[data-clock-announcement]').textContent=label;p.querySelectorAll('[data-clock-step]').forEach(b=>{b.disabled=nextBookingTime(input.value,b.dataset.clockPart,Number(b.dataset.clockStep))===input.value;});input.dispatchEvent(new Event('change',{bubbles:true}));}pickers.forEach(p=>{const trigger=p.querySelector('.time-trigger'),popover=p.querySelector('.time-popover');trigger.addEventListener('click',()=>{const opening=popover.hidden;closeAll();popover.hidden=!opening;trigger.setAttribute('aria-expanded',String(opening));if(opening)popover.querySelector('[data-clock-value="hour"]').focus();});p.querySelectorAll('[data-clock-step]').forEach(b=>b.addEventListener('click',()=>update(p,b.dataset.clockPart,Number(b.dataset.clockStep))));p.querySelectorAll('[data-clock-value]').forEach(el=>el.addEventListener('keydown',e=>{if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();update(p,el.dataset.clockValue,e.key==='ArrowUp'?1:-1);}}));p.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closeAll();trigger.focus();}});p.addEventListener('focusout',e=>{if(!p.contains(e.relatedTarget))closeAll();});});document.addEventListener('click',e=>{if(!e.target.closest('[data-time-picker]'))closeAll();});}

function booking(){return `<div class="booking-shell" id="booking"><div class="booking-tabs"><span>Book your island drive</span><a href="reservations.html">My reservation</a></div><form id="booking-form" class="booking-panel"><div class="booking-grid"><div class="field"><label for="pickup-location">Pick-up location</label><select id="pickup-location" name="pickupLocation" required>${options(D.bookingLocations)}</select></div><div class="field"><label for="pickup-date">Pick-up date & time</label><div class="date-pair"><input type="date" id="pickup-date" name="pickupDate" required aria-label="Pick-up date">${timePicker('pickupTime','Pick-up time')}</div></div><div class="field"><label for="return-location">Return location</label><select id="return-location" name="returnLocation" required>${options(D.bookingLocations)}</select></div><div class="field"><label for="return-date">Return date & time</label><div class="date-pair"><input type="date" id="return-date" name="returnDate" required aria-label="Return date">${timePicker('returnTime','Return time')}</div></div><div class="field"><label for="vehicle-type">Vehicle type</label><select id="vehicle-type" name="vehicleType"><option value="All">All vehicles</option>${['Car','SUV','Convertible','Van'].map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label for="passengers">Passengers</label><select id="passengers" name="passengers"><option value="0">Any</option>${[2,5,7,8,9,12].map(n=>`<option value="${n}">${n} passengers</option>`).join('')}</select></div><button class="btn blue" type="submit">Search cars</button></div></form></div>`;}
function card(v){const name=esc(v.brand+' '+v.model.trim());const icon=paths=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">${paths}</svg>`;const rate=v.publishedRate;const money=n=>'$'+Number(n).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});return `<article class="vehicle-card"><div class="car-heading"><h3>${name}</h3><p>${esc(v.type)}</p></div><div class="car-picture" style="--ground-w:${(v.cardGround?.width||0)*100}%;--ground-h:${(v.cardGround?.height||0)*100}%;--ground-w-pad:${(v.cardGround?.width||0)*16}px;--ground-h-pad:${(v.cardGround?.height||0)*24}px"><img loading="${page==='home'?'eager':'lazy'}" decoding="async" src="${v.cardImage||v.image}" alt="${name}" width="600" height="350"></div><div class="car-body"><div class="specs"><span aria-label="${v.numberOfPassengers} passengers">${icon('<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v2"/>')}${v.numberOfPassengers} seats</span><span aria-label="${v.amountOfLuggage} luggage">${icon('<rect x="5" y="6" width="14" height="14" rx="2"/><path d="M9 6V3h6v3M9 10v6m6-6v6M8 20v1m8-1v1"/>')}${v.amountOfLuggage} ${v.amountOfLuggage===1?'bag':'bags'}</span><span aria-label="${v.numberOfDoors} doors">${icon('<path d="M4 20V10l7-7h9v17H4Zm1-9h14M13 4v7m2 4h2"/>')}${v.numberOfDoors} doors</span>${v.transmission?`<span>${icon('<circle cx="12" cy="12" r="9"/><path d="M8 7v5h8V7m-4 5v5"/>')}${esc(v.transmission)}</span>`:''}</div></div><div class="card-bottom"><div class="car-rate-copy">${rate?`<strong>${money(rate.day)}<span class="rate-unit">/day</span></strong><small>${money(rate.week)}/week</small>`:'<strong>Check rates</strong><small>At booking</small>'}</div><button data-vehicle="${v.id}" aria-label="Reserve ${name}">Reserve</button></div></article>`;}
function homeFleetAction(type){const count=D.fleet.filter(v=>type==='All'||v.type===type).length;if(count<=8)return '';const labels={All:'View full fleet',Car:'View all cars',SUV:'View all SUVs',Convertible:'View all convertibles',Van:'View all vans'};return button(labels[type],type==='All'?'fleet.html':`fleet.html?type=${encodeURIComponent(type)}`,'outline');}
function home(){return `${header()}<div class="hero"><main id="main"><div class="hero-copy"><h1>YOUR JOURNEY<br><span>STARTS HERE</span></h1><p class="hero-sub">From your first beach stop to the road less travelled.</p></div>${booking()}<div class="hero-stage"><div class="ground"></div><div class="hero-vehicle"><img class="hero-car" src="assets/hero-jetta-side.webp" alt="Blue Volkswagen Jetta sedan from the Dollar Thrifty fleet" fetchpriority="high"></div></div></main></div><div class="hero-scroll-strip"><a class="scroll-indicator" href="#fleet" aria-label="Explore below">↓</a></div><section class="section soft-section" id="fleet"><div class="wrap"><div class="section-head"><div><h2>Find The Car<br>For Your Journey</h2></div></div><div class="category-tabs" id="home-categories">${['All','Car','SUV','Convertible','Van'].map(t=>`<button class="${t==='All'?'active':''}" data-home-type="${t}">${t==='All'?'Featured vehicles':t==='Car'?'Cars':t==='Van'?'Vans':t==='SUV'?'SUVs':'Convertibles'}</button>`).join('')}</div><div class="fleet-grid" id="featured-cars">${[87,152,6,70,4,71,118,182].map(id=>card(D.fleet.find(v=>v.id===id))).join('')}</div><div class="fleet-more" id="home-fleet-action">${homeFleetAction('All')}</div></div></section><section class="company-numbers wrap" aria-label="Dollar Thrifty by the numbers"><dl class="numbers-grid"><div><dt>Car rental in St. Maarten / St. Martin</dt><dd>#1</dd></div><div><dt>Years of local experience</dt><dd>30<span>+</span></dd></div><div><dt>Vehicle choices</dt><dd>50</dd></div><div><dt>Rental centers</dt><dd>9</dd></div></dl></section><section class="why-choose section wrap" aria-labelledby="why-choose-title"><div class="benefits-heading"><h2 id="why-choose-title">Why Choose Us?</h2></div><div class="benefits-grid company-statements">${[["Diverse Fleet", "Choose from a wide range of vehicles designed for comfort, safety, and your travel needs."], ["Best Rates", "Enjoy competitive rental rates and special offers for returning customers."], ["Great Services", "Count on friendly, attentive service for a smooth rental experience from start to finish."]].map(([title,text],i)=>`<article class="benefit-card"><div class="benefit-icon ${i===1?'dark':'blue'}" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${['<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M8 9h8M8 13h5"/>','<circle cx="12" cy="12" r="9"/><path d="M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9m3-10v12"/>','<path d="M21 11a8 8 0 0 1-8 8H7l-4 3v-7a8 8 0 1 1 18-4Z"/><path d="M7 9h10M7 13h7"/>'][i]}</svg></div><h3>${esc(title)}</h3><p>${esc(text)}</p></article>`).join('')}</div></section><section class="section wrap"><h2>How It Works</h2><ol class="how-grid journey-steps" aria-label="Rental steps"><li class="journey-step"><div class="step-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/></svg></div><span class="step-connector" aria-hidden="true"></span><h3>Find Your Car</h3><p>Choose your dates, locations and the type of car that works for you.</p></li><li class="journey-step"><div class="step-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 3v4m8-4v4M4 10h16m-12 5 3 3 5-5"/></svg></div><span class="step-connector" aria-hidden="true"></span><h3>Confirm Your Reservation</h3><p>Complete your booking on the original website. Your confirmation arrives by email.</p></li><li class="journey-step"><div class="step-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="m4 12 2-6h12l2 6M4 12h16v6H4zM6 18v2m12-2v2M7 15h1m8 0h1M4 9H2m18 0h2"/></svg></div><h3>Arrive & Hit The Road</h3><p>Print your confirmation and present it to the agent upon arrival at St. Maarten / St. Martin Airport.</p></li></ol></section><section class="section wrap booking-invite-section" aria-labelledby="booking-invite-title"><div class="booking-invite"><div class="booking-invite-copy"><h2 id="booking-invite-title">Ready To<br>Hit The Road?</h2><p>Choose your dates, find your car, and get ready to explore St. Maarten / St. Martin.</p>${button('Book a car','index.html#booking','blue')}</div><div class="booking-invite-visuals" aria-hidden="true"><div class="invite-vehicle invite-vehicle-low"><span>YOUR ISLAND DRIVE</span><img src="assets/fleet-profile-70.webp" alt="" loading="lazy"><strong>Volkswagen Jetta</strong></div><div class="invite-vehicle invite-vehicle-high"><span>ROOM TO EXPLORE</span><img src="assets/fleet-profile-87.webp" alt="" loading="lazy"><strong>Jeep Wrangler</strong></div></div></div></section>${footer()}`;}
const titles={fleet:['Find Your<br>Ideal Ride','Explore the company’s fleet. Choose a category, compare specifications and continue to live booking.'],locations:['Always A<br>Good Start','Find rental offices and collection points around St. Maarten, with addresses, contact details and listed opening hours.'],about:['About Us','Meet Dollar / Thrifty St. Maarten / St. Martin.'],services:['The Little Extras<br>The Better Drive','Explore the services and optional equipment listed by Dollar / Thrifty.'],contact:['Let’s Talk<br>Island Plans','Contact the St. Maarten team for help with your rental.'],reservations:['Your Next Stop:<br>Your Reservation','Find, review or manage your reservation through the original Dollar / Thrifty website.'],faq:['Good Questions<br>Clearer Journeys','The original company’s frequently asked questions.'],policies:['Before You<br>Hit The Road','Rental terms and policy documents, kept at their original source.'],'cookie-policy':['Cookie Policy','Original company policy wording, reproduced from the source website.'],'content-checklist':['Every Detail<br>Accounted For','Content inventory, source notes and integration handoff for this redesign.']};
function pageShell(content){const t=titles[page];return `${header()}<div class="page-top"><main id="main" class="page-title wrap"><div class="breadcrumb"><a href="index.html">Home</a> <span aria-hidden="true">&gt;</span> <span aria-current="page">${esc(page.replaceAll('-',' ').replace(/\b\w/g,c=>c.toUpperCase()))}</span></div>${['fleet','locations','about'].includes(page)?'':`<span class="eyebrow">Dollar / Thrifty · St. Maarten / St. Martin</span>`}<h1>${t[0]}</h1><p>${t[1]}</p></main></div><div class="content wrap">${content}</div>${footer()}`;}
function fleetPage(){return `<div id="trip-summary" class="notice booking-summary"></div><div class="fleet-toolbar"><div class="category-tabs" id="fleet-categories">${['All','Car','SUV','Convertible','Van'].map(t=>`<button data-type="${t}" class="${t==='All'?'active':''}">${t==='All'?'All vehicles':t==='Car'?'Cars':t==='SUV'?'SUVs':t==='Van'?'Vans':'Convertibles'}</button>`).join('')}</div><div class="fleet-tools"><input id="fleet-search" type="search" aria-label="Search fleet" placeholder="Search a brand or model..."><details class="fleet-filter-menu"><summary><svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"><path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2" fill="white"/><circle cx="15" cy="12" r="2" fill="white"/><circle cx="9" cy="18" r="2" fill="white"/></svg>Filters<span id="fleet-filter-count" hidden></span></summary><div class="fleet-filter-panel"><h3>Filter Vehicles</h3><label for="filter-passengers">Passengers</label><select id="filter-passengers"><option value="0">Any number</option>${[2,5,7,8,9,12].map(n=>`<option value="${n}">${n} passengers</option>`).join('')}</select><label for="filter-transmission">Transmission</label><select id="filter-transmission"><option value="">Any transmission</option>${['Automatic','Manual'].map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</select><button type="button" id="clear-fleet-filters">Clear filters</button></div></details></div></div><span id="fleet-count" class="sr-only" role="status" aria-live="polite"></span><div id="fleet-grid" class="fleet-grid"></div>`;}

function locationsPage(){return `<div class="locations-grid">${D.locations.map(l=>`<article class="location-card">${l.photo?`<img src="${l.photo}" alt="${esc(l.label)}" loading="lazy">`:`<div class="missing-photo" aria-label="Location photo unavailable">⌖</div>`}<div class="location-body"><h2>${esc(l.label)}</h2><p>${esc(l.address)}</p><p>Opening hours: ${esc(l.openingTime)} – ${esc(l.closingTime)}</p><p><a href="tel:${esc(l.telephoneNumber.split(' ext')[0].replace(/[^+\d]/g,''))}">${esc(l.telephoneNumber)}</a></p><a class="btn outline location-action" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(l.label+' '+l.address+' St. Maarten')}" target="_blank" rel="noopener">Open in maps</a></div></article>`).join('')}</div>`;}
const story=`Dollar/Thrifty Car Rental is regarded as the #1 Car Rental in St. Maarten/St.Martin with the most beautiful facilities and an amazing selection of vehicle models to suit your every need and desire. We are committed to providing great service, and secure and reliable rentals at value rates. Dollar/Thrifty St. Maarten is also committed to provide added value to your vacation experience on our dual island nation (Dutch and French) located at 175 miles due east of Puerto Rico in the outer ring of the North Eastern Caribbean. St. Maarten/Saint Martin is a popular vacation destination due to its Duty Free Shopping, 37 marvelous beaches, a spending gastronomy and a sparkling nightlife. Dollar/Thrifty provides you the means of economic and extravagant transportation so that you can explore the island to the fullest.`;
const serviceCopy=[`Dollar/Thrifty Car Rental has the most state of the art and modern car rental facilities here in St. Maarten. We have been known for years as the best franchise on the island with the entire premises designed for super-efficient and fast, personalized service.`,`In an effort to help you enjoy your vacation on the island to the fullest, we have compiled a large selection of cars for you to choose from.`,`You will find a variety of cars, vans, jeeps etc. at the best prices, with reliable service, and added convenience. Dollar/Thrifty Car Rental features a new fleet of cars, and consists of Quality Vehicle that are kept in top condition in order to ensure the comfort and safety of all potential customers.`];
const featureCopy=[['Diverse Fleet','We at Dollar/Thrifty Car Rental offer our clients with excellent options of fleet diversity to best suite your every need for transportation.Be rest assured with the knowledge and feeling that our vehicles are guaranteed to deliver comfort and safety.'],['Best Rates','With great vehicles comes great pricing as well. We ensure every customer receives excellent rates. Our rates are guaranteed to be the most competitive and always up to date with the current market standards. Specials are also always provided for our loyal customers who receive discounts each time they book with us!'],['Great Services','Customer service is a #1 priority for Dollar/Thrifty. We take pride to ensure every customer leaves our facilities with a warm, happy feeling, and a great experience which makes them always want to return and rent from us. Our Agents diligently assist in any area to ensure our customers always leave satisfied, without inconveniences, and knowing that they have been taken care of with the utmost effort.']];
function aboutPage(){return `<div class="split"><div class="prose"><span class="eyebrow">Our story</span><h2 style="margin-top:0">We Are<br>Dollar / Thrifty</h2><p>${story}</p></div><div class="photo-block"><img src="assets/slider-2.jpg" alt="Dollar Thrifty St. Maarten facilities" loading="lazy"></div></div><div class="prose narrow"><h2>Our Service</h2>${serviceCopy.map(p=>`<p>${p}</p>`).join('')}</div><div class="gallery">${[1,2,3,4,5,6].map(n=>`<img src="assets/slider-${n}.jpg" alt="Dollar Thrifty company gallery, photograph ${n}" loading="lazy">`).join('')}</div><div class="section-head team-heading"><div><h2>Meet The Team</h2><p class="team-intro">Meet the people behind Dollar/Thrifty in St. Maarten / St. Martin, helping you get on your way.</p></div></div><div class="team-grid">${D.staff.map(s=>`<article class="person"><div class="person-photo"><img src="${s.photo}" alt="${esc(s.name)}" loading="lazy"></div><div class="person-caption"><h3>${esc(s.name)}</h3><p>${esc(s.position)}</p></div></article>`).join('')}</div>`;}
function servicesPage(){return `<div class="prose narrow"><h2 style="margin-top:0">Start Your Stay With Ease</h2><p>Booking with us is fast and easy, and we assure you that your car will be waiting for you at the Airport. After you make your reservation, you will receive your confirmation via email. Simply print your confirmation, and present it to our agent upon arrival at the St. Maarten/St. Martin Airport.</p><ul class="review-list"><li>Unlimited free mileage</li><li>Offices located near airport</li><li>Free shuttle transfer to and from the airport</li><li>Car delivery by locations</li></ul><p class="source-note">The original homepage also advertises “Rent 6 days, get 7th day free!” This offer has not been verified for current dates. Confirm eligibility and current rates with the company before booking.</p></div><div class="service-grid" style="margin-top:35px">${featureCopy.map(([h,p])=>`<article class="service-card"><h3>${h}</h3><p>${p}</p></article>`).join('')}</div><div class="prose"><h2>Make The Drive Your Own</h2><p>These extras are listed by the original reservation system. Current pricing and availability are confirmed during booking.</p></div><div class="service-grid">${D.options.map(o=>`<article class="service-card"><h3>${esc(o.name)}</h3><p>${esc(o.description)}</p>${o.usesAmount?`<small>Original booking quantity limit: ${o.amountMax}</small>`:''}</article>`).join('')}</div><p class="source-note" style="margin-top:25px">The source Collision Insurance description advertises “It starts from only $10.00 daily! (\"price\" may vary depending on the size of the rental vehicle)”. This is preserved as a source note, not a current quote. The original options data contains conflicting amounts. Confirm current pricing on the original site.</p>`;}
function contactPage(){return `<div class="contact-grid"><aside class="contact-card"><span class="eyebrow">We’re here to help</span><h2>Hello From<br>St Maarten</h2><p>102 Airport Road, St. Maarten<br><a href="tel:+17215452393">+1 (721) 545-2393</a></p><p><a href="mailto:customerservice@dollarthriftysxm.com">customerservice@dollarthriftysxm.com</a></p><p>U.S. toll free<br><a href="tel:+18669780932">+1 (866) 978-0932</a><br>Canada toll free<br><a href="tel:+14166282863">+1 (416) 628-2863</a></p><a class="textlink" href="locations.html">All locations & opening hours ${arrow}</a></aside><div><h3>Have A Question?</h3><p class="source-note">Compose an email below, or use the company's original secure contact form.</p><form id="contact-form" class="form-grid"><div class="field"><label for="first-name">First name *</label><input id="first-name" name="firstName" autocomplete="given-name" required></div><div class="field"><label for="last-name">Last name *</label><input id="last-name" name="lastName" autocomplete="family-name" required></div><div class="field full"><label for="email">Email *</label><input id="email" type="email" name="email" autocomplete="email" required></div><div class="field full"><label for="subject">Subject *</label><input id="subject" name="subject" required></div><div class="field full"><label for="question">Question *</label><textarea id="question" name="question" required></textarea></div><small class="full">This opens your email application with your message. The original contact form states: “By submitting this form you agree to the Privacy Policy of this website and the storing of the submitted information.” Its linked document is the <a href="${BASE}assets/documents/Dollar_Thrifty_Rental_Policies.pdf" target="_blank" rel="noopener"><u>Rental Policies</u></a>.</small><div class="full dialog-actions"><button class="btn blue" type="submit">Compose email</button><a class="textlink" href="${BASE}contact" target="_blank" rel="noopener">Original contact form</a></div></form></div></div>`;}
function reservationsPage(){return `<div class="lookup"><span class="eyebrow">Manage your trip</span><h2 style="font-size:32px">Find Your Reservation</h2><p>Use your confirmation number on the original website to look up your booking, review your details, or request a change or cancellation.</p><p>Your confirmation number stays on the company's website. Reservation lookup and changes continue through its existing system.</p>${button('Open reservation lookup',BASE+'my-reservations','blue')}</div><div class="prose narrow"><h2>Have Your Confirmation Ready</h2><p>The original lookup asks for your confirmation number (for example, X6RENT11). Your booking confirmation is sent by email. For help, contact <a href="mailto:customerservice@dollarthriftysxm.com"><u>customerservice@dollarthriftysxm.com</u></a> or call <a href="tel:+17215452393"><u>+1 (721) 545-2393</u></a>.</p></div>`;}
function faqPage(){return `<div class="fleet-tools"><input id="faq-search" aria-label="Search frequently asked questions" type="search" placeholder="Search a question…"></div><div class="faq-list">${D.faqs.map((f,i)=>`<details class="faq-item"><summary>${esc(f.question)}</summary><p>${esc(f.answer)}</p>${i===2?'<small>Source note: this answer repeats the driving-area information. Payment guidance needs confirmation from the company.</small>':''}</details>`).join('')}<p class="hidden" id="faq-empty">No matching questions. Contact the team for help.</p></div>`;}
function policiesPage(){return `<div class="narrow"><div class="doc-card"><div><h2>Terms And Conditions</h2><p>Original PDF · Opens from the company's website</p></div>${button('Read document',BASE+'assets/documents/Dollar_Thrifty_Terms_and_Conditions.pdf','outline')}</div><div class="doc-card"><div><h2>Rental Policies</h2><p>Original PDF · Opens from the company's website</p></div>${button('Read document',BASE+'assets/documents/Dollar_Thrifty_Rental_Policies.pdf','outline')}</div><div class="doc-card"><div><h2>Cookie Policy</h2><p>Original website policy wording</p></div>${button('Read policy','cookie-policy.html','outline')}</div><p class="source-note">The company’s original booking flow requires acceptance of both Terms and Conditions and Rental Policies. Those acceptance steps remain on the original booking website. Policy documents are linked directly so their wording remains at the authoritative source.</p></div>`;}
function cookiePage(){const headings=['Categories of cookies used on this site','Essential Cookies','Session Cookie','Authentication Cookie','Non-essential Cookies: Performance Cookies','Google Analytics','Google reCAPTCHA','Cookies served through our website','Your Choices','Using your Browser'];return `<div class="notice">This is the original company's cookie policy, preserved for reference. This redesign does not load the original Google Analytics, Maps scripts or reCAPTCHA. Original policy descriptions apply to the original website. Booking preferences on this redesign are stored only in this tab's session storage.</div><div class="prose narrow">${D.cookieText.map(t=>`<div class="policy-block">${headings.includes(t.trim())?`<strong>${esc(t)}</strong>`:esc(t)}</div>`).join('')}<a class="textlink" href="${BASE}cookie-policy">Read policy at original source</a></div>`;}
function checklist(){return `<div class="notice">Source audit: 27 October 2026. This is a redesign preview. All transactions continue on the original company's website. Rates and availability are not represented as live data.</div><div class="table-scroll"><table><thead><tr><th>Original content / function</th><th>Redesign destination</th><th>Status</th></tr></thead><tbody>${[['Home introduction & service benefits','Homepage / Services','Preserved; longer company statements on Services'],['Fleet catalogue, photos, descriptions & specifications','Our fleet','54 active models; search, category filters & vehicle detail dialogs'],['Six reservation search fields','Homepage booking panel','Retained; filters local catalogue; live booking handoff'],['Renter details, extras, coupon, policy acceptance, confirmation & submission','Original booking website','Preserved destination; requires re-entry across domains'],['Reservation lookup, modification & cancellation','My reservation','Connected to original reservation system'],['Location directory, hours, addresses & phones','Locations','10 published directory entries; original six bookable options retained'],['Our Story, Our Service & company gallery','About us','Original wording, six gallery photographs'],['Meet the Staff','About us','13 staff entries, source names, roles and photographs'],['Feature statements and original advertised offer','Services & extras','Preserved with current-offer verification note'],['Six optional booking extras','Services & extras / original booking','Descriptions and quantity limits retained; current prices not quoted'],['Contact form & contact channels','Contact / footer','Labeled email composer and original form link; no fake submission'],['Terms and Conditions / Rental Policies','Policies / footer','Original PDF destinations; unchanged authoritative wording'],['Cookie Policy','Cookie Policy / footer','Original text retained; contextual note for redesign'],['Social profiles & original credits','Footer','Original Facebook, Instagram and Logic. IT Solutions credit'],['Original language switcher','Original website','Original language behavior needs verification; redesign is English'],['FAQ questions and answers','FAQ','All three source entries; duplicate payment answer flagged']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="prose narrow"><h2>Still Needs Attention</h2><ul class="review-list"><li>Booking integration: the original application transfers dates, locations and vehicle data through same-origin sessionStorage. No supported cross-domain handoff was found. The redesign links to the original homepage and explicitly asks visitors to re-enter details. A documented booking API or same-domain deployment is needed for seamless transfer.</li><li>Reservation lookup, booking creation, add-ons, coupons, payment-related fields, email confirmation and changes/cancellations are intentionally completed in the original system. No live reservation was submitted during verification.</li><li>Original contact submission uses reCAPTCHA and an email endpoint. This redesign provides a working email composer and an original contact form link; direct form submission needs an approved backend integration.</li><li>The homepage says nine centers, while the directory contains ten locations and the booking selector offers six. The redesign retains the directory and the exact booking location options.</li><li>Directory opening hours are 08:00–18:00; the original booking selector permits 08:00–17:00. Confirm this difference with the company.</li><li>The “How to Pay” FAQ duplicates the driving-area answer. It is preserved and flagged. No payment rules were invented.</li><li>The Simpson Bay Resort & Marina Residences location photo is inaccessible: its source URL returns application HTML. A neutral location marker appears in its place.</li><li>Fleet catalogue photos are only 600×350. The hero uses an AI-assisted background extraction/upscale of the original Jeep Wrangler photo; the original catalogue image appears in its detail card. A licensed high-resolution original photograph would improve production fidelity.</li><li>The original “Rent 6 days, get 7th day free!” promotion and insurance advertised amounts were not verified for current dates. They appear only as attributed source notes, not active offers or quotes.</li><li>Some source fleet fields are blank (including BAIC BJ40 transmission); the redesign leaves those specifications absent.</li><li>The original Cookie Policy is reproduced for reference. Privacy/cookie wording must be reviewed for the final production analytics and booking configuration.</li></ul><h2>Design Choices</h2><p>A warm off-white canvas, oversized two-line headline, floating white booking panel, large fleet vehicle cutout and angled Thrifty-blue ground band follow the supplied visual composition. Original Dollar red is reserved for small accents. The layout moves from booking and fleet discovery to local service, pickup information and company details.</p><p>Responsive grids, readable form labels, visible keyboard focus, semantic links, native date inputs, reduced-motion support and lazy-loaded secondary images keep the experience usable across screen sizes.</p></div>`;}
function filteredFleet(){return D.fleet.filter(v=>(selectedType==='All'||v.type===selectedType)&&(!query||(v.brand+' '+v.model).toLowerCase().includes(query))&&(!trip||!Number(trip.passengers)||v.numberOfPassengers>=Number(trip.passengers))&&(!fleetFilters.passengers||v.numberOfPassengers===fleetFilters.passengers)&&(!fleetFilters.transmission||v.transmission===fleetFilters.transmission));}
function renderFleet(){let list=filteredFleet();$('#fleet-grid').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h3>No Matching Vehicles</h3><p>Try another category, search term or filter.</p><button class="btn" id="reset-fleet">Reset filters</button></div>';$('#fleet-count').textContent=`${list.length} matching vehicle models`;const active=Object.values(fleetFilters).filter(Boolean).length;const badge=$('#fleet-filter-count');badge.hidden=!active;badge.textContent=String(active);document.querySelectorAll('[data-type]').forEach(b=>{b.classList.toggle('active',b.dataset.type===selectedType);b.setAttribute('aria-pressed',String(b.dataset.type===selectedType));});}
function tripText(){return trip?`${trip.pickupLocation} · ${trip.pickupDate} ${trip.pickupTime} → ${trip.returnLocation} · ${trip.returnDate} ${trip.returnTime}`:'Choose your dates and locations on the original booking website.';}
function openVehicle(id){const v=D.fleet.find(v=>v.id===Number(id));if(!v)return;const dialog=$('#detail-dialog');dialog.innerHTML=`<div class="dialog-content"><button class="dialog-close" aria-label="Close vehicle details">×</button><span class="eyebrow">${esc(v.type)} · ${esc(v.classCode||'Fleet vehicle')}</span><h2>${esc(v.brand+' '+v.model.trim())}</h2><img src="${v.image}" alt="${esc(v.brand+' '+v.model)}"><dl><dt>Passengers</dt><dd>${v.numberOfPassengers}</dd><dt>Luggage</dt><dd>${v.amountOfLuggage}</dd><dt>Doors</dt><dd>${v.numberOfDoors}</dd>${v.transmission?`<dt>Transmission</dt><dd>${esc(v.transmission)}</dd>`:''}<dt>Air conditioning</dt><dd>${v.hasAirConditioning?'Yes':'No'}</dd><dt>Multimedia unit</dt><dd>${v.hasMultiMediaUnit?'Yes':'No'}</dd></dl><p>${esc(v.description)}</p><div class="notice">Live rates and availability are confirmed on the original Dollar / Thrifty website. Please re-enter your dates, locations and vehicle preference there.${trip?`<br><strong>Your plan:</strong> ${esc(tripText())}`:''}</div><div class="dialog-actions">${button('Continue to live booking',BASE,'blue')}<button class="btn outline dialog-dismiss">Keep exploring</button></div></div>`;dialog.showModal();}
function wire(){const menu=$('.menu-toggle');menu?.addEventListener('click',()=>{const opened=$('#main-nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(opened));menu.setAttribute('aria-label',opened?'Close navigation':'Open navigation');});document.addEventListener('click',e=>{const vehicle=e.target.closest('[data-vehicle]');if(vehicle)openVehicle(vehicle.dataset.vehicle);if(e.target.closest('.dialog-close,.dialog-dismiss'))$('#detail-dialog').close();if(e.target.id==='detail-dialog')$('#detail-dialog').close();if(e.target.id==='reset-fleet'){trip=null;selectedType='All';query='';fleetFilters={passengers:0,transmission:''};$('#filter-passengers').value='0';$('#filter-transmission').value='';$('#fleet-search').value='';$('#trip-summary').classList.remove('visible');sessionStorage.removeItem('sxm-trip');renderFleet();}});
if(page==='home'){wireTimePickers();const date=(offset)=>{const now=new Date(new Date().toLocaleString('en-US',{timeZone:'America/Lower_Princes'}));now.setDate(now.getDate()+offset);return `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;};const pickup=$('#pickup-date'),ret=$('#return-date');pickup.min=date(0);pickup.value=date(1);ret.min=date(2);ret.value=date(4);pickup.addEventListener('change',()=>{const d=new Date(pickup.value+'T12:00:00');d.setDate(d.getDate()+1);const min=d.toISOString().slice(0,10);ret.min=min;if(ret.value<min)ret.value=min;});$('#booking-form').addEventListener('submit',e=>{e.preventDefault();const t=Object.fromEntries(new FormData(e.currentTarget));const start=new Date(t.pickupDate+'T'+t.pickupTime),end=new Date(t.returnDate+'T'+t.returnTime);if(end-start<86400000){ret.setCustomValidity('Return must be at least 24 hours after pickup.');ret.reportValidity();return;}ret.setCustomValidity('');sessionStorage.setItem('sxm-trip',JSON.stringify(t));location.href='fleet.html?trip=1';});ret.addEventListener('input',()=>ret.setCustomValidity(''));$('#booking-form').returnTime.addEventListener('change',()=>ret.setCustomValidity(''));document.querySelectorAll('[data-home-type]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-home-type]').forEach(c=>{c.classList.toggle('active',c===b);c.setAttribute('aria-pressed',String(c===b));});let list=b.dataset.homeType==='All'?[87,152,6,70,4,71,118,182].map(id=>D.fleet.find(v=>v.id===id)):D.fleet.filter(v=>v.type===b.dataset.homeType).slice(0,8);$('#featured-cars').innerHTML=list.map(card).join('');$('#home-fleet-action').innerHTML=homeFleetAction(b.dataset.homeType);}));}
if(page==='fleet'){const category=new URLSearchParams(location.search).get('type');if(['Car','SUV','Convertible','Van'].includes(category))selectedType=category;try{if(new URLSearchParams(location.search).has('trip'))trip=JSON.parse(sessionStorage.getItem('sxm-trip'));}catch{}if(trip){selectedType=trip.vehicleType||'All';$('#trip-summary').classList.add('visible');$('#trip-summary').innerHTML=`<strong>Your island plan</strong><br>${esc(tripText())}<br>These are catalogue matches, not live availability. Continue on the original site to re-enter your details and confirm a booking. <a href="index.html#booking"><u>Edit trip</u></a>`;}renderFleet();document.querySelectorAll('[data-type]').forEach(b=>b.addEventListener('click',()=>{selectedType=b.dataset.type;renderFleet();}));$('#fleet-search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();renderFleet();});[['filter-passengers','passengers'],['filter-transmission','transmission']].forEach(([id,key])=>$('#'+id).addEventListener('change',e=>{fleetFilters[key]=key==='transmission'?e.target.value:Number(e.target.value);renderFleet();}));$('#clear-fleet-filters').addEventListener('click',()=>{fleetFilters={passengers:0,transmission:''};$('#filter-passengers').value='0';$('#filter-transmission').value='';renderFleet();});}
if(page==='faq')$('#faq-search').addEventListener('input',e=>{let count=0;document.querySelectorAll('.faq-item').forEach(d=>{let match=d.textContent.toLowerCase().includes(e.target.value.toLowerCase());d.classList.toggle('hidden',!match);if(match)count++;});$('#faq-empty').classList.toggle('hidden',count>0);});
if(page==='contact')$('#contact-form').addEventListener('submit',e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.currentTarget));location.href=`mailto:customerservice@dollarthriftysxm.com?subject=${encodeURIComponent(f.subject)}&body=${encodeURIComponent(f.question+'\n\nFrom: '+f.firstName+' '+f.lastName+'\nEmail: '+f.email)}`;});}
async function init(){try{D=await fetch('data.json').then(r=>{if(!r.ok)throw Error('Content unavailable');return r.json();});const content={fleet:fleetPage,locations:locationsPage,about:aboutPage,services:servicesPage,contact:contactPage,reservations:reservationsPage,faq:faqPage,policies:policiesPage,'cookie-policy':cookiePage,'content-checklist':checklist};$('#app').innerHTML=(page==='home'?home():pageShell(content[page]()))+'<dialog id="detail-dialog" aria-label="Vehicle details"></dialog>';wire();}catch(e){$('#app').innerHTML=`<div class="wrap section"><h1>Let’s Get You On Your Way</h1><p>The redesign's content could not be loaded. The original booking website is available below.</p>${button('Visit Dollar / Thrifty',BASE)}</div>`;console.error(e);}}
init();
